                int t1 = (int) ((long) C[i - 1][j - 1] * (i + 1) % mod);
                int t2 = (int) (((long) f[j - 1] * g[i - j] % mod) + ((long) g[j - 1] * f[i - j] % mod));
                g[i] = (int) ((g[i] + (long) t1 * t2 % mod) % mod);

                int add = (int) ((long) C[i - 1][j - 1] * (((long)(j - 1) * j / 2) + ((long)(i - j + 1) * (i - j) / 2)) % mod);
                g[i] = (int) ((g[i] + (long) add * f[j - 1] % mod * f[i - j] % mod) % mod);
            }
        }

        n++;
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                dp[i][j] = 0;
                dp2[i][j] = 0;
            }
        }

        dp[0][0] = 1;
        dp2[0][0] = 0;

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                for (int k = 0; j + k <= m && i + k + 1 <= n; ++k) {
                    int c = C[j + k][j];
                    long val1 = (long) dp[i][j] * f[k] % mod;
                    long val2 = (long) dp2[i][j] * c % mod;
